function openBird(phases){const cur=currentPhase(phases);showSheet(`<div class="sheethead"><div><div class="eyebrow">Now → Flaine</div><h2>The whole plan</h2></div><button class="btn small ghost" data-close>Close</button></div>${[...phases].filter(p=>p.from).sort((a,b)=>a.from.localeCompare(b.from)).map(p=>`<div class="phase ${p.id===cur.id?'current':''}"><h3>${esc(p.name)}</h3><div class="tiny muted">${fmt(p.from)} → ${fmt(p.to)}</div><p class="small">${esc(p.summary)}</p><div class="tiny muted">${(p.rules||[]).map(esc).join(' · ')}</div></div>`).join('')}`,{full:true})}
