async function editTemplate(t=null){const exs=await db.all('exercises'),d=t?structuredClone(t):{name:'New template',type:'strength',description:'',items:[]};showSheet(`<div class="sheethead"><div><div class="eyebrow">Template</div><h2>${esc(d.name)}</h2></div><button class="btn small ghost" data-close>Close</button></div><div class="field"><label>Name</label><input id="teName" value="${esc(d.name)}"></div><div class="field"><label>Description</label><input id="teDesc" value="${esc(d.description||'')}"></div>${d.type==='strength'?`${d.items.map((x,i)=>{const e=exs.find(z=>z.id===x.exerciseId);return`<section class="card teitem"><div class="row"><strong>${esc(e?.name||'Unknown')}</strong><button class="btn small danger" data-te-del="${i}">×</button></div><div class="grid4" style="margin-top:10px">${tplField('Sets','sets',x.sets,i)}${tplField('Rep min','repMin',x.repMin,i)}${tplField('Rep max','repMax',x.repMax,i)}${tplField('Target','target',x.target,i)}${tplField('Rest','rest',x.rest,i)}${tplField('Start kg','startWeight',x.startWeight,i)}${tplField('Later sets','eventualSets',x.eventualSets,i)}</div><div class="field"><label>Note</label><input data-tpl="${i}:note" value="${esc(x.note||'')}"></div></section>`}).join('')}<div class="row"><select id="tplAddEx"><option value="">Add exercise…</option>${exs.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select><button class="btn small blue" id="tplAdd">Add</button></div>`:`<p class="muted">Activity template editing is intentionally simple in this build.</p>`}<button class="btn blue block" id="saveTemplate" style="margin-top:14px">Save template</button>`,{full:true});function capture(){d.name=$('#teName').value;d.description=$('#teDesc').value;if(d.type==='strength')$$('[data-tpl]').forEach(el=>{const [i,f]=el.dataset.tpl.split(':');d.items[Number(i)][f]=f==='note'?el.value:Number(el.value)})}$$('[data-te-del]').forEach(b=>b.onclick=()=>{capture();d.items.splice(Number(b.dataset.teDel),1);closeSheet();editTemplate(d)});$('#tplAdd')?.addEventListener('click',()=>{capture();const eid=Number($('#tplAddEx').value);if(eid){const e=exs.find(x=>x.id===eid);d.items.push({exerciseId:eid,sets:2,repMin:8,repMax:12,target:8,rest:e.defaultRest||90,startWeight:0,eventualSets:3,optional:false,rehab:false,note:'',warmups:[],progression:'double'});closeSheet();editTemplate(d)}});$('#saveTemplate').onclick=async()=>{capture();if(d.id)await db.put('templates',d);else await db.add('templates',d);closeSheet();openTemplateLibrary()}}
