function openAISettings(s){const has=!!localStorage.getItem('openaiKey');showSheet(`<div class="sheethead"><div><div class="eyebrow">Local AI</div><h2>Coach connection</h2></div><button class="btn small ghost" data-close>Close</button></div><div class="card" style="background:var(--amber-soft)"><p class="small" style="margin:0">The key lives only in this browser/device and is excluded from backup. Use a dedicated API project/key with a low spend limit.</p></div><div class="field"><label>API key</label><input id="apiKey" type="password" value="${has?'••••••••••••••••••••':''}" placeholder="sk-..."></div><div class="field"><label>Model</label><input id="aiModel" value="${esc(s.aiModel||'gpt-5.6')}"></div><div class="wrap"><button class="btn blue" id="saveAI">Save locally</button><button class="btn secondary" id="testAI">Test</button>${has?'<button class="btn danger" id="removeAI">Remove</button>':''}</div><div id="aiStatus" class="small muted" style="margin-top:12px"></div>`);$('#saveAI').onclick=async()=>{const v=$('#apiKey').value;if(v&&!v.includes('•'))localStorage.setItem('openaiKey',v.trim());await saveSettings({aiModel:$('#aiModel').value.trim()||'gpt-5.6'});$('#aiStatus').textContent='Saved locally.'};$('#testAI').onclick=async()=>{const st=$('#aiStatus');st.textContent='Testing…';try{const out=await callOpenAI('Reply with exactly: connection works.');st.textContent=out.trim()}catch(e){st.textContent=friendlyAIError(e)}};$('#removeAI')?.addEventListener('click',()=>{localStorage.removeItem('openaiKey');closeSheet();render()})}
async function exportData(){const out={version:VERSION,exportedAt:new Date().toISOString(),stores:{}};for(const n of STORE_NAMES)out.stores[n]=await db.all(n);const blob=new Blob([JSON.stringify(out,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`slope-backup-${isoDate()}.json`;a.click();URL.revokeObjectURL(url)}
